(() => { const setLanguage=language=>{const lang=language==='en'?'en':'vi';document.documentElement.lang=lang;document.title=(lang==='en'?'Privacy policy':'Chính sách bảo mật')+' | thefirstworkshop';document.querySelectorAll('[data-language]').forEach(el=>el.hidden=el.dataset.language!==lang);document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));try{localStorage.setItem('tfw-language',lang)}catch{}};let initial='vi';try{initial=localStorage.getItem('tfw-language')||'vi'}catch{}document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>setLanguage(el.dataset.lang)));setLanguage(initial);})();
